catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
    if (isLoading || newValue == '') {
        return;
    }
    // var enteredDate = new Date(g_form.getValue("question_date_of_expense"));
    var date1 = newValue;

// Step 1: Parse the first date into a JavaScript Date object
var parts = date1.split("/"); // Split into day, month, year
var parsedDate1 = new Date(parts[2], parts[1] - 1, parts[0]); // Create Date object (months are zero-based)

// alert (parsedDate1);
    var today = new Date();
// alert(today);
    // Remove the time part from today's date for accurate comparison
    today.setHours(0, 0, 0, 0);
	parsedDate1.setHours(0, 0, 0, 0);

    if (parsedDate1 > today) {
        // Show an error message and clear the invalid value
        // g_form.addErrorMessage("You cannot select a future date for refund.");
		alert('You cannot select a future date for refund.')
        g_form.clearValue('question_date_of_expense');
    }
    //Type appropriate comment here, and begin script below

}
